def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The five-cell vertical pattern is copied, centered on each 8 marker.
    pattern = [7, 1, 7, 7, 7]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    for r, c in markers:
        for k, value in enumerate(pattern):
            rr = r + k - 2
            if 0 <= rr < h:
                out[rr][c] = value
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft(); comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append(comp)
    template = max(comps, key=len)
    r0=min(r for r,c in template); r1=max(r for r,c in template)
    c0=min(c for r,c in template); c1=max(c for r,c in template)
    shape={(r-r0,c-c0):grid[r][c] for r,c in template}
    # Singleton non-background objects are the locations to receive the pattern.
    markers=[(r,c) for comp in comps if comp is not template and len(comp)==1 for r,c in comp]
    out=[row[:] for row in grid]
    ar=(r1-r0)//2; ac=(c1-c0)//2
    for r,c in markers:
        for (dy,dx),v in shape.items():
            y,x=r+dy-ar,c+dx-ac
            if 0<=y<h and 0<=x<w: out[y][x]=v
    return out
